from lib import *
chapter(6,'maths','playing-with-constructions','Playing with Constructions',
 ('Art with a ruler and a compass','Artists make beautiful designs using only a ruler and a compass. We too can draw squares, rectangles and circles that fit together. Let us construct and explore.'),
 [('Squares and rectangles',['A rectangle has four sides and four right angles, and opposite sides are equal.','A square is a special rectangle with all four sides equal.','A rectangle has two lines joining opposite corners called diagonals.']),
  ('Constructing squares and rectangles',['Use a ruler to draw a base of the length you want. Use a set square or protractor to draw 90 degrees at each end.','Mark the other sides to the length required and join them.','Check by measuring the diagonals. In a rectangle the two diagonals are equal.']),
  ('Exploring rectangles',['Different rectangles can have the same perimeter. Try a fixed length of string and make different rectangles.','Among rectangles with a given perimeter, the square gives the largest area.']),
  ('Diagonals of rectangles and squares',['The diagonals of a rectangle are equal and they cut each other into equal parts at the middle.','In a square the diagonals are equal, they cross at right angles and they also bisect each other.']),
  ('Points equidistant from two points',['A compass lets us mark points that are the same distance from a given point. Drawing arcs from two points finds a point equally far from both.','The line joining all such points is the perpendicular bisector of the segment.'])],
 [('Construct a rectangle 6 cm by 4 cm.',[('Draw a base of 6 cm.','Use a ruler.'),('Draw 90 degree angles at both ends, mark 4 cm up, and join the tops.','Then check that the diagonals are equal.')]),
  ('What is the perimeter of the square drawn with side 5 cm?',[('A square has four equal sides.','All sides are 5 cm.'),('4 times 5 is 20 cm.','Perimeter.')])],
 ('Explain how you can check a rectangle without a protractor.',['Measure both diagonals.','If they are equal and opposite sides are equal, it is a rectangle.'],['Thinking all quadrilaterals with equal diagonals are rectangles.','Drawing without checking the right angles.']),
 ['Squares and rectangles have four right angles.','A square has four equal sides.','Diagonals of a rectangle are equal.','A compass finds points equal distance from two given points.'],
 [mcq('c8-1',1,'How many right angles does a rectangle have?','4',[('2','All four corners are right angles.'),('0','A rectangle has square corners.')],'Each corner is 90 degrees.'),
  tf('c8-2',1,'Every square is a rectangle.',True,'A square has four right angles and opposite sides equal.'),
  mcq('c8-3',1,'The diagonals of a rectangle are','equal in length',[('always perpendicular','That is true for a square only.'),('parallel','Diagonals meet at the centre.')],'Measure them to check.'),
  mcq('c8-4',1,'Which tool draws a circle?','Compass',[('Ruler','A ruler draws straight lines.'),('Protractor','A protractor measures angles.')],'A compass swings a fixed radius.'),
  num('c8-5',2,'The perimeter of a square with side 9 cm is',36,'4 times 9.',[(81,'81 is the area.')],'cm'),
  mcq('c8-6',2,'Among all rectangles with the same perimeter, the largest area belongs to the','square',[('thinnest rectangle','A very thin rectangle has a tiny area.'),('longest rectangle','Long rectangles have small areas.')],'A square is the best use of a fixed boundary.'),
  tf('c8-7',2,'Diagonals of a square cross at right angles.',True,'That is a special property of the square.'),
  mcq('c8-8',2,'A point equally far from two points A and B lies on the','perpendicular bisector of AB',[('line AB itself','Only the midpoint of AB lies there.'),('a ray from A','Distances to A and B differ.')],'Arcs from A and B meet on it.'),
  num('c8-9',3,'A rectangle has perimeter 24 cm and length 8 cm. Its breadth is',4,'2 times (8 plus b) is 24, so b is 4.',[(16,'Subtract 8 from 12, not 24.')],'cm'),
  mcq('c8-10',3,'To construct a square of side 5 cm you need','four 5 cm sides and four right angles',[('four 5 cm sides only','A rhombus also has equal sides but no right angles.'),('four right angles only','A rectangle has them but unequal sides.')],'Both conditions are needed.')],
 keep=['rectangle','square','diagonal'])
